use vstd::prelude::*;

verus! {

    // is_greater returns true iff n is strictly greater than every element of a.
    fn is_greater(n: i32, a: &Vec<i32>) -> (ret: bool)
        requires
            a.len() > 0,
        ensures
            // For all valid indices j in a, n > a@[j]
            ret == forall |j: usize| j < a.len() ==> n > a@[j],
    {
        // ok will track that n > a@[j] for all j < i
        let mut ok: bool = true;
        let mut i: usize = 0;
        while i < a.len()
            invariant
                // i never exceeds the array length
                i <= a.len(),
                // ok is equivalent to "for all j < i, n > a@[j]"
                ok == forall |j: usize| j < i ==> n > a@[j],
            decreases a.len() - i,
        {
            // If we ever find an element a[i] ≥ n, we set ok to false
            if !(n > *a.index(i)) {
                ok = false;
            }
            i = i + 1;
        }
        ret = ok;
    }

}

